package com.example.rokidkeyboardbridge;
import android.app.*;import android.content.*;import android.content.pm.*;import android.content.res.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;
/** Actual production layout with synthetic information, no sensors/network/user preferences. */
public final class FullBodyInformationDeviceChecks {
 static int n;static void ok(boolean b,String m){n++;if(!b)throw new AssertionError(m);}
 static Field f(String name)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f;}
 static void set(MainActivity owner,String name,Object value)throws Exception{f(name).set(owner,value);}
 static void call(MainActivity owner,String method)throws Exception{Method m=MainActivity.class.getDeclaredMethod(method);m.setAccessible(true);m.invoke(owner);}
 static void layout(FrameLayout root,int w,int h){root.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));root.layout(0,0,w,h);}
 public static int run(Context host)throws Exception{
  n=0;File apk=new File(host.getFilesDir(),"glass.apk");AssetManager assets=AssetManager.class.getDeclaredConstructor().newInstance();AssetManager.class.getMethod("addAssetPath",String.class).invoke(assets,apk.getPath());ApplicationInfo app=new ApplicationInfo(host.getApplicationInfo());app.sourceDir=app.publicSourceDir=apk.getPath();Context c=new ContextWrapper(host){public AssetManager getAssets(){return assets;}public ApplicationInfo getApplicationInfo(){return app;}};
  int sample=0;
  for(int[] size:new int[][]{{480,640},{640,480},{320,240}}){
   MainActivity owner=new MainActivity();Method attach=ContextWrapper.class.getDeclaredMethod("attachBaseContext",Context.class);attach.setAccessible(true);attach.invoke(owner,c);Field window=Activity.class.getDeclaredField("mWindow");window.setAccessible(true);window.set(owner,new Dialog(c).getWindow());
   FrameLayout root=new FrameLayout(c);root.setBackgroundColor(Color.BLACK);LinearLayout content=new LinearLayout(c);content.setOrientation(1);root.addView(content,new FrameLayout.LayoutParams(-1,-1));TextView comment=new TextView(c);comment.setTextColor(Color.WHITE);comment.setText("合成の回答本文。情報欄と重ならないコメント領域。");content.addView(comment,new LinearLayout.LayoutParams(-1,-1));
   Class<?> mascot=Class.forName(MainActivity.class.getName()+"$MascotView");Constructor<?> ctor=mascot.getDeclaredConstructor(MainActivity.class,Context.class);ctor.setAccessible(true);View face=(View)ctor.newInstance(owner,c);root.addView(face,new FrameLayout.LayoutParams(96,96));
   TextView info=new TextView(c);HealthHudTypography.apply(info);info.setTextColor(Color.LTGRAY);String text="2099/1/1(木) 12:34\nBAT 80% Wi-Fi / NET OK\n歩数 4321  収支 -120kcal\n水分：合成のお知らせ\n晴れ 20℃\n現在地：合成地点\n通知あり";info.setText(text);FrameLayout.LayoutParams original=new FrameLayout.LayoutParams(216,72);original.leftMargin=96;root.addView(info,original);
   TextView status=new FullBodyStatusView(c,()->true,()->{});status.setText("AI：合成の回答を作成中");root.addView(status,new FrameLayout.LayoutParams(216,12));LinearLayout buttons=new LinearLayout(c);root.addView(buttons,new FrameLayout.LayoutParams(-1,20,Gravity.BOTTOM));TextView clock=new TextView(c);root.addView(clock,new FrameLayout.LayoutParams(190,28));LinearLayout nav=new LinearLayout(c);nav.setVisibility(View.GONE);root.addView(nav,new FrameLayout.LayoutParams(1,1));ScrollView overview=new ScrollView(c);overview.setVisibility(View.GONE);root.addView(overview,new FrameLayout.LayoutParams(1,1));
   set(owner,"hudRoot",root);set(owner,"hudContent",content);set(owner,"mascotView",face);set(owner,"info",info);set(owner,"status",status);set(owner,"buttonPanel",buttons);set(owner,"navigationClock",clock);set(owner,"navigationPanel",nav);set(owner,"navigationOverviewScroll",overview);set(owner,"glanceHudVisible",true);
   c.getSharedPreferences("navigation_display",0).edit().putBoolean("full_body_mode",true).commit();layout(root,size[0],size[1]);call(owner,"applyFullBodyLayout");layout(root,size[0],size[1]);
   TextView full=(TextView)f("fullBodyInfo").get(owner);ScrollView band=(ScrollView)f("fullBodyInfoScroll").get(owner);TextView operation=(TextView)f("fullBodyStatus").get(owner);
   ok(full.getText().toString().equals(text),"face/full-body information parity");ok(band.getVisibility()==View.VISIBLE,"full-body information visible");ok(clock.getVisibility()==View.GONE,"no duplicate clock over comments");ok(info.getVisibility()==View.GONE,"original face-position info hidden");ok(content.getPaddingTop()>=band.getBottom(),"information band cannot overlap comment column");ok(size[1]-content.getPaddingBottom()<=operation.getTop(),"operation band cannot overlap comment column");ok(full.getLayout()!=null&&full.getLayout().getLineCount()>=7,"all information rows present");ok(full.getMeasuredHeight()>=full.getLayout().getLineBottom(full.getLineCount()-1),"long information remains scrollable without lost rows");ok(status.getVisibility()==View.GONE,"legacy overlay stays hidden");
   info.setText(text.replace("80%","79%").replace("4321","4322"));call(owner,"refreshFullBodyStatus");ok(full.getText().toString().equals(info.getText().toString()),"live info changes reach full body");
   int children=root.getChildCount();call(owner,"applyFullBodyLayout");layout(root,size[0],size[1]);ok(root.getChildCount()==children,"repeated layout does not duplicate information");ok(full.getText().toString().equals(info.getText().toString()),"cached-size layout retains current info");
   Bitmap bitmap=Bitmap.createBitmap(size[0],size[1],Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(Color.BLACK);root.draw(canvas);try(FileOutputStream output=host.openFileOutput("full-body-information-"+sample+++".png",0)){bitmap.compress(Bitmap.CompressFormat.PNG,100,output);}bitmap.recycle();
   c.getSharedPreferences("navigation_display",0).edit().putBoolean("full_body_mode",false).commit();call(owner,"restoreStandardVisualLayout");ok(band.getVisibility()==View.GONE,"face mode removes the full-body band");ok(info.getVisibility()==View.VISIBLE,"face mode restores its original information");ok(((FrameLayout.LayoutParams)info.getLayoutParams()).leftMargin==96,"face information original geometry restored");
   FullBodyMascotView body=(FullBodyMascotView)f("fullBodyImage").get(owner);body.releaseInspection();((android.os.Handler)f("handler").get(owner)).removeCallbacksAndMessages(null);
  }assets.close();return n;
 }
}
